fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // tol is strictly positive by assumption
    // Compute the difference as i16 to avoid overflow when subtracting
    let diff = (a as i16) - (b as i16);
    // Check if difference is strictly between -tol and tol
    diff > -(tol as i16) && diff < (tol as i16)
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Assume a.len() == b.len() and tol > 0 by problem statement
    // For each pair, check closeness using is_close_i8
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| is_close_i8(x, y, tol))
        .collect()
}